def solve(d):
    h,w=len(d),len(d[0])
    cc=cc_of(d,1); uniq=[frozenset(c) for c in cc]
    def enclosed(zeros):
        seen=set(); st=[]
        for z in sorted(zeros):
            y,x=z
            if y in (0,h-1) or x in (0,w-1):
                if z not in seen: seen.add(z); st.append(z)
        while st:
            y,x=st.pop()
            for dy in (-1,0,1):
                for dx in (-1,0,1):
                    n=(y+dy,x+dx)
                    if n in zeros and n not in seen:
                        seen.add(n); st.append(n)
        return zeros-seen
    e=[row[:] for row in d]
    for u in uniq:
        ys=[p[0] for p in u]; xs=[p[1] for p in u]
        r0,r1,c0,c1=min(ys),max(ys),min(xs),max(xs)
        # enclosed zeros within this comp's bbox (orthogonal flood from outside bbox through zeros, 4-dir)
        outside={(y,x) for y in range(max(0,r0-1),min(h,r1+2)) for x in range(max(0,c0-1),min(w,c1+2)) if d[y][x]==0 and not(r0<=y<=r1 and c0<=x<=c1)}
        seens=set(); st=list(outside)
        seen_={z for z in st}
        while st:
            y,x=st.pop()
            for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                n=(y+dy,x+dx)
                if 0<=n[0]<h and 0<=n[1]<w and d[n[0]][n[1]]==0 and n not in seen_:
                    seen_.add(n); st.append(n)
        enc={z for z in outside if z not in seen_}
        if not enc: continue
        for (hy,hx) in enc:
            if any(abs(hy-y)<=1 and abs(hx-x)<=1 and (hy,hx)!=(y,x) for y,x in u):
                e[hy][hx]=3
        ring=[]
        for y in range(max(0,min(p[0] for p in u)-1),min(h-1,max(p[0] for p in u)+1)):
            for x in range(max(0,min(p[1] for p in u)-1),min(w-1,max(p[1] for p in u)+1)):
                if d[y][x]==0 and any(abs(y-p[0])<=1 and abs(x-p[1])<=1 and (y,x)!=(p[0],p[1]) for p in u):
                    ring.append((y,x))
        for y,x in ring: e[y][x]=2
    return e
